mapper.select:
SELECT w.id, w.name, w.cover_image_url, w.status, AS work_date, t.id AS type_id, t.name AS type_name, at.id AS adaptation_type_id, at.name AS adaptation_type_name FROM
LEFT JOIN broadcast_type t ON t.id = w.broadcast_type_id LEFT JOIN book_type t ON t.id = w.book_type_id
LEFT JOIN adaptation_type at ON at.id = w.adaptation_type_id WHERE
AND (LOWER(w.name) LIKE LOWER(#{pattern}) ESCAPE '!' OR EXISTS (SELECT 1 FROM alias al WHERE al.target_type = AND al.target_id = w.id AND LOWER(al.alias_name) LIKE LOWER(#{pattern}) ESCAPE '!') OR EXISTS (SELECT 1 FROM series_item si JOIN series s ON s.id = si.series_id WHERE si.work_type = AND si.work_id = w.id AND LOWER(s.name) LIKE LOWER(#{pattern}) ESCAPE '!'))
AND w.broadcast_type_id = #{filter.broadcastTypeId} AND w.book_type_id = #{filter.bookTypeId} AND w.adaptation_type_id = #{filter.adaptationTypeId} AND w.status = #{filter.status}
AND IS NULL AND BETWEEN #{startDate} AND #{endDate}
AND (SELECT COUNT(DISTINCT tr.tag_id) FROM tag_relation tr WHERE tr.target_type = AND tr.target_id = w.id AND tr.tag_id IN #{id}) = #{tagCount}
ORDER BY
LOWER(w.name) COLLATE "C" work_date
ASCDESC NULLS LAST, w.id DESC
